routes.script:
LET $u = QUERY SELECT id FROM {{t:users}} WHERE username = {{body.username}} LIMIT 1;
IF LEN($u.rows) > 0
  RETURN 409 { "ok": false, "error": "USER_EXISTS" };
END
EXEC INSERT INTO {{t:users}} (only_id, username, password_hash, display_name) VALUES ({{onlyId}}, {{body.username}}, SM4_ENC({{body.password}}, 'clickbuild-key'), {{body.display_name}});
LET $t = TOKEN NEW { "onlyId": {{onlyId}}, "username": {{body.username}} };
RETURN 201 { "ok": true, "onlyId": {{onlyId}}, "token": $t.token };

LET $u = QUERY SELECT only_id, password_hash, display_name FROM {{t:users}} WHERE username = {{body.username}} LIMIT 1;
IF LEN($u.rows) == 0
  RETURN 401 { "ok": false, "error": "NO_USER" };
END
IF SM4_DEC($u.rows[0].password_hash, 'clickbuild-key') != {{body.password}}
  RETURN 401 { "ok": false, "error": "BAD_PASSWORD" };
END
LET $t = TOKEN NEW { "onlyId": $u.rows[0].only_id, "username": {{body.username}} };
RETURN 200 { "ok": true, "token": $t.token, "name": $u.rows[0].display_name };

LET $c = QUERY SELECT * FROM {{t:main}} WHERE id = {{id}} LIMIT 1;
LET $l = QUERY SELECT * FROM {{t:lesson}} WHERE course_id = {{id}} ORDER BY id;
RETURN 200 { "course": $c.rows, "lessons": $l.rows };

LET $e = QUERY SELECT id FROM {{t:main}} WHERE course_id = {{id}} AND user_only_id = {{user.onlyId}} LIMIT 1;
IF LEN($e.rows) > 0
  RETURN 409 { "ok": false, "error": "ALREADY_ENROLLED" };
END
LET $c = QUERY SELECT seats, enrolled FROM {{t:course}} WHERE id = {{id}} LIMIT 1;
IF LEN($c.rows) == 0
  RETURN 404 { "ok": false, "error": "NO_COURSE" };
END
IF $c.rows[0].enrolled >= $c.rows[0].seats
  RETURN 409 { "ok": false, "error": "FULL" };
END
EXEC INSERT INTO {{t:main}} (course_id, user_only_id) VALUES ({{id}}, {{user.onlyId}});
EXEC UPDATE {{t:course}} SET enrolled = enrolled + 1 WHERE id = {{id}};
RETURN 201 { "ok": true };
